  const { child, base } = await startServer(tmpDir());
  try {
    const res = await fetch(`${base}/api/feed?limit=50`);
    assert.equal(res.status, 200);
    const data = await res.json();
    assert.equal(data.events.length, 8);
    assert.equal(data.hasMore, false);
    assert.equal(data.latestSeq, 8);
    // 升序且序号连续
    const seqs = data.events.map((e) => e.seq);
    assert.deepEqual(seqs, [1, 2, 3, 4, 5, 6, 7, 8]);
