import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';

function tmpDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ktv-server-'));
}

function startServer(dir) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [path.join(import.meta.dirname, '..', 'src', 'server.js')], {
      env: { ...process.env, PORT: '0', DATA_DIR: dir },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let buf = '';
    const onData = (chunk) => {
      buf += chunk;
      const m = buf.match(/http:\/\/localhost:(\d+)/);
      if (m) {
        child.stdout.off('data', onData);
        child.stderr.off('data', onErr);
        resolve({ child, base: `http://localhost:${m[1]}` });
      }
    };
    const onErr = (chunk) => { reject(new Error(chunk.toString())); };
    child.stdout.on('data', onData);
    child.stderr.on('data', onErr);
    child.on('error', reject);
  });
}

// Node fetch 不允许非 Latin-1 头（浏览器 fetch 可直发 UTF-8），中文名需 percent-encode，
// 与 server.js 的 operatorFromReq 解码对应
const L = (s) => encodeURIComponent(s);
const MANAGER_HEADERS = {
  'X-Role': 'MANAGER',
  'X-User-Id': 'u-mgr',
  'X-User-Name': L('值班经理-老赵'),
};

async function postTransition(base, roomId, body, headers) {
  const res = await fetch(`${base}/api/rooms/${roomId}/transitions`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...headers },
    body: JSON.stringify(body),
  });
  const data = await res.json();
  assert.ok(res.ok, data.error);
  return data;
}

test('GET /api/feed：首屏返回播种动态（seq 升序、带标签与包厢名）', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    const res = await fetch(`${base}/api/feed?limit=50`);
    assert.equal(res.status, 200);
    const data = await res.json();
    assert.equal(data.events.length, 8);
    assert.equal(data.hasMore, false);
    assert.equal(data.latestSeq, 8);
    // 升序且序号连续
    const seqs = data.events.map((e) => e.seq);
    assert.deepEqual(seqs, [1, 2, 3, 4, 5, 6, 7, 8]);
    // 与不可变交接记录同源，且带展示标签
    const last = data.events.at(-1);
    assert.ok(last.roomName && last.actionLabel && last.toStateLabel && last.operatorRoleLabel);
  } finally {
    child.kill();
  }
});

test('断线重连：afterSeq 只补缺口、顺序正确，幂等重放不产生重复动态', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // 把 R303（待清洁 v1）推进：保洁接单 → 报检 → 经理驳回（填原因）
    const rooms = await (await fetch(`${base}/api/rooms`)).json();
    const r303 = rooms.rooms.find((r) => r.id === 'R303');
    assert.equal(r303.version, 1);

    const claim = await postTransition(base, 'R303', {
      action: 'CLAIM', expectedVersion: 1,
    }, { 'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐') });
    const submit = await postTransition(base, 'R303', {
      action: 'SUBMIT_CLEAN', expectedVersion: 2,
    }, { 'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐') });
    const reject = await postTransition(base, 'R303', {
      action: 'REJECT_INSPECTION', expectedVersion: 3, reason: '卫生间水渍未擦干',
      idempotencyKey: 'idem-test-reject',
    }, { ...MANAGER_HEADERS, 'Idempotency-Key': 'idem-test-reject' });

    // 同一幂等键重试（即使版本已过期）：返回首次结果，不新增事件
    const replay = await postTransition(base, 'R303', {
      action: 'REJECT_INSPECTION', expectedVersion: 99, reason: '卫生间水渍未擦干',
      idempotencyKey: 'idem-test-reject',
    }, MANAGER_HEADERS);
    assert.equal(replay.duplicated, true);
    assert.equal(replay.event.seq, reject.event.seq);

    // 看板在 seq=8（播种最后一条）时断线：重连只拿到 9/10/11，顺序即发生顺序
    const gap = await (await fetch(`${base}/api/feed?afterSeq=8&limit=50`)).json();
    assert.deepEqual(gap.events.map((e) => e.seq), [9, 10, 11]);
    assert.deepEqual(gap.events.map((e) => e.action), ['CLAIM', 'SUBMIT_CLEAN', 'REJECT_INSPECTION']);
    assert.equal(gap.events.at(-1).reason, '卫生间水渍未擦干');
    assert.equal(gap.latestSeq, reject.event.seq);
    assert.equal(gap.hasMore, false);

    // 全量动态中同一笔变更只有一条
    const all = await (await fetch(`${base}/api/feed?limit=50`)).json();
    assert.equal(all.events.length, 11);
    assert.equal(all.events.filter((e) => e.seq === reject.event.seq).length, 1);
    assert.equal(new Set(all.events.map((e) => e.seq)).size, all.events.length);
  } finally {
    child.kill();
  }
});

test('分页：缺口超过一页时从最早页开始，hasMore/nextCursor 可遍历全部', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    const rooms = await (await fetch(`${base}/api/rooms`)).json();
    const r303 = rooms.rooms.find((r) => r.id === 'R303');
    await postTransition(base, 'R303', { action: 'CLAIM', expectedVersion: r303.version }, {
      'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐'),
    });

    // afterSeq=0、每页 3 条：从最早一页（1,2,3）开始
    let data = await (await fetch(`${base}/api/feed?afterSeq=0&limit=3`)).json();
    assert.deepEqual(data.events.map((e) => e.seq), [1, 2, 3]);
    assert.equal(data.hasMore, true);
    assert.equal(data.nextCursor, 3);

    // 翻到最后一页
    data = await (await fetch(`${base}/api/feed?afterSeq=${data.nextCursor}&limit=3`)).json();
    assert.deepEqual(data.events.map((e) => e.seq), [4, 5, 6]);
    assert.equal(data.nextCursor, 6);
    data = await (await fetch(`${base}/api/feed?afterSeq=${data.nextCursor}&limit=3`)).json();
    assert.deepEqual(data.events.map((e) => e.seq), [7, 8, 9]);
    assert.equal(data.hasMore, false);
    assert.equal(data.nextCursor, null);

    // 非法游标 400
    const bad = await fetch(`${base}/api/feed?afterSeq=abc`);
    assert.equal(bad.status, 400);

    // 已追平后重连：空缺口
    const empty = await (await fetch(`${base}/api/feed?afterSeq=${data.latestSeq}&limit=3`)).json();
    assert.deepEqual(empty.events, []);
    assert.equal(empty.hasMore, false);
  } finally {
    child.kill();
  }
});

