  fs.mkdirSync(dir, { recursive: true });
  this.rooms = new Map();       // id -> room
  this.events = new Map();      // id -> event[]
  this.idempotency = new Map(); // key -> {roomId, event}
  this.locks = new Map();       // roomId -> Promise 链（串行化同包厢写入）
  this.alerts = new Map();      // `${roomId}:${state}` -> alert
  this.listeners = new Set();
  this.seqMax = 0;              // 跨包厢全局单调序号（交接动态的总顺序/断线补齐游标）
  this._load();
}

_file() {
  return path.join(this.dir, 'events-db.json');
}

_load() {
  const f = this._file();
  if (!fs.existsSync(f)) return;
  try {
    const data = JSON.parse(fs.readFileSync(f, 'utf8'));
    for (const r of data.rooms || []) {
      this.rooms.set(r.id, { ...r });
      this.events.set(r.id, []);
    }
    // 旧版本落盘的事件可能没有全局 seq：按发生时间确定总顺序后补号；
    // 新数据沿用事件上的 seq，重启后序号不回退
    const loaded = (data.events || []).filter((ev) => this.events.has(ev.roomId));
    if (loaded.some((ev) => !Number.isInteger(ev.seq))) {
      loaded.sort((a, b) => {
        const c = new Date(a.at) - new Date(b.at);
        if (c) return c;
        if (a.roomId !== b.roomId) return a.roomId < b.roomId ? -1 : 1;
        return a.version - b.version;
      });
      for (const ev of loaded) ev.seq = ++this.seqMax;
    } else {
      this.seqMax = loaded.reduce((m, ev) => Math.max(m, ev.seq), 0);
    }
    for (const ev of loaded) this.events.get(ev.roomId).push(ev);
    // 按 seq 校正各包厢内事件顺序
    for (const evs of this.events.values()) {
      evs.sort((a, b) => a.seq - b.seq);
    }
    for (const [id] of this.rooms) this._rebuildRoomFromEvents(id, { touch: false });
    for (const [k, v] of Object.entries(data.alerts || {})) this.alerts.set(k, { ...v });
  } catch (e) {
    console.error('加载数据失败，使用空数据启动:', e.message);
  }
}

_persist() {
  const data = {
    rooms: [...this.rooms.values()].map(({ id, name }) => ({ id, name })),
    events: [...this.events.values()].flat(),
    alerts: Object.fromEntries(this.alerts),
  };
  const tmp = this._file() + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(data));
  fs.renameSync(tmp, this._file());
}

