  if (!fs.existsSync(f)) return;
  try {
    const data = JSON.parse(fs.readFileSync(f, 'utf8'));
    for (const r of data.rooms || []) {
      // 旧数据没有 active 字段，默认在营
      this.rooms.set(r.id, { active: true, ...r });
      this.events.set(r.id, []);
    }
    const transitions = (data.events || []).filter((ev) => this.events.has(ev.roomId));
    const entries = (data.roomEntries || []).filter((en) => this.rooms.has(en.roomId));
    // 旧版本落盘的记录可能没有全局 seq：流转事件 + 管理审计一起按发生时间确定总顺序后补号；
