    const all = [...transitions, ...entries];
    if (all.some((x) => !Number.isInteger(x.seq))) {
      all.sort((a, b) => {
        const c = new Date(a.at) - new Date(b.at);
        if (c) return c;
        if (a.roomId !== b.roomId) return a.roomId < b.roomId ? -1 : 1;
        return (a.version || 0) - (b.version || 0);
      });
      for (const x of all) x.seq = ++this.seqMax;
