function renderInactive() {
  const box = document.getElementById('inactiveBox');
  const list = document.getElementById('inactiveList');
  const isManager = roleEl.value === 'MANAGER';
  const inactive = state.rooms.filter(r => r.active === false);
  if (!inactive.length) { box.style.display = 'none'; return; }
  box.style.display = '';
  list.innerHTML = inactive.map(r => `
    <span class="inactive-item">
      <span>${escapeHtml(r.name)} <span class="tag">${escapeHtml(r.id)} · ${r.stateLabel}</span></span>
      <button class="ghost" data-inactive-history="${r.id}">交接记录</button>
      ${isManager ? `<button class="primary" data-activate="${r.id}">启用</button>` : ''}
    </span>`).join('');
  list.querySelectorAll('[data-inactive-history]').forEach(btn => {
    btn.onclick = () => {
      const room = state.rooms.find(r => r.id === btn.dataset.inactiveHistory);
      showHistory(room);
    };
  });
  list.querySelectorAll('[data-activate]').forEach(btn => {
    btn.onclick = () => activateRoom(btn.dataset.activate);
  });
}

