let promptPending = null;
function openPrompt({ title, hint, label1, value1, placeholder1, label2, value2, placeholder2, onConfirm }) {
  promptPending = { onConfirm };
  document.getElementById('promptTitle').textContent = title;
  const hintEl = document.getElementById('promptHint');
  hintEl.textContent = hint || '';
  const i1 = document.getElementById('promptInput1');
  const i2 = document.getElementById('promptInput2');
  i1.placeholder = placeholder1 || '';
  i1.value = value1 || '';
  i1.style.display = label1 ? '' : 'none';
  i1.previousLabel?.remove();
  i2.placeholder = placeholder2 || '';
