        ${item.reason ? ` · <span class="reason">原因：${escapeHtml(item.reason)}</span>` : ''}
        ${item.idempotencyKey && item.idempotencyKey.startsWith('idem-retry') ? ' · 重试命中' : ''}
      </div>
    </div>`).join('');
}
function manageLabel(a) {
  return {
    ROOM_CREATE: '新增包厢', ROOM_RENAME: '包厢改名',
    ROOM_DEACTIVATE: '包厢停用', ROOM_ACTIVATE: '包厢启用',
  }[a] || a;
}
function renderManageItem(en) {
  let detail = '';
  if (en.manageAction === 'ROOM_CREATE') detail = `新增包厢「${escapeHtml(en.toName || en.roomName)}」，初始可开放`;
  else if (en.manageAction === 'ROOM_RENAME') detail = `改名：${escapeHtml(en.fromName)} → ${escapeHtml(en.toName)}（历史记录保留原名）`;
  else if (en.manageAction === 'ROOM_DEACTIVATE') detail = `停用包厢「${escapeHtml(en.roomName)}」（装修改造）${en.reason ? `，原因：${escapeHtml(en.reason)}` : ''}`;
  else detail = `重新启用包厢「${escapeHtml(en.roomName)}」`;
  return `
    <div class="item">
      <div class="row1">
        <span class="who">${escapeHtml(en.operatorName)}（${roleLabel(en.operatorRole)}）· ${manageLabel(en.manageAction)}</span>
        <span class="t">${fmtClock(en.at)}</span>
      </div>
      <div class="row2">${escapeHtml(en.roomId)} · ${detail}</div>
    </div>`;
}
function roleLabel(r) { return { FRONT: '前台', CLEANER: '保洁', MANAGER: '值班经理' }[r] || r; }
// 动态中的房间名以“发生时的快照”为准（改名不追溯），缺失才回退当前名
function feedRoomName(item) { return item.roomName || state?.rooms?.find(r => r.id === item.roomId)?.name || item.roomId; }
function escapeHtml(s) { return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }

