// ---- 包厢管理 ----

test('新增包厢：初始 OPEN/v0/无责任人，立即出现在快照且有审计条目', async () => {
  const s = freshStore();
  const { room, entry } = await s.createRoom({ id: 'R309', name: '309（中包）' }, MANAGER);
  assert.equal(room.state, STATE.OPEN);
  assert.equal(room.version, 0);
  assert.equal(room.responsible, null);
  assert.equal(room.active, true);
  assert.equal(entry.kind, 'manage');
  assert.equal(entry.manageAction, 'ROOM_CREATE');
  assert.equal(entry.seq, 1);
  assert.ok(s.snapshot().rooms.some(r => r.id === 'R309'));
  // 编号留空自动分配（现有 R1 → R301）
  const auto = await s.createRoom({ name: '301（小包）' }, MANAGER);
  assert.equal(auto.room.id, 'R301');
  // 编号非法 / 重复
  await assert.rejects(s.createRoom({ id: 'X1', name: 'x' }, MANAGER), /R 开头/);
  await assert.rejects(s.createRoom({ id: 'R309', name: 'y' }, MANAGER), e => e.status === 409);
  await assert.rejects(s.createRoom({ id: 'R310', name: '' }, MANAGER), /名称/);
});

test('包厢管理 RBAC：仅值班经理可新增/改名/停用', async () => {
  const s = freshStore();
  await assert.rejects(s.createRoom({ id: 'R310', name: 'x' }, FRONT), e => e.status === 403);
  await assert.rejects(s.createRoom({ id: 'R310', name: 'x' }, CLEANER), e => e.status === 403);
  await s.renameRoom('R1', { name: '一号包厢' }, FRONT).then(
    () => assert.fail('前台不应能改名'),
    e => assert.equal(e.status, 403),
  );
});

test('改名：只改当前展示名，历史事件保留旧房间名快照', async () => {
  const s = freshStore();
  s.rooms.get('R1').name = '旧名包厢';
  const r1 = await run(s, ACTION.CHECK_IN, {}, FRONT);
  assert.equal(r1.event.roomName, '旧名包厢');
  await s.renameRoom('R1', { name: '新名包厢' }, MANAGER);
  const r2 = await run(s, ACTION.CHECK_OUT, {}, FRONT);
  assert.equal(r2.event.roomName, '新名包厢');
  // 历史记录里第一条仍是旧名，不被追溯
  const hist = s.history('R1', 10);
  assert.equal(hist.find(e => e.seq === r1.event.seq).roomName, '旧名包厢');
  assert.equal(hist.find(e => e.seq === r2.event.seq).roomName, '新名包厢');
  assert.equal(s.rooms.get('R1').state, STATE.TO_CLEAN);
  assert.equal(s.rooms.get('R1').version, 2);
});

test('停用：非 OPEN 包厢拒绝；停用后隐藏/不可流转但历史可查；启用后恢复', async () => {
  const s = freshStore();
  await run(s, ACTION.CHECK_IN, {}, FRONT); // IN_USE，不能停用
  await assert.rejects(
    s.setRoomActive('R1', { active: false, reason: '装修' }, MANAGER),
    e => e.status === 409 && e.code === 'ROOM_BUSY',
  );
  // 走完流程回到 OPEN
  await run(s, ACTION.CHECK_OUT, {}, FRONT);
  await run(s, ACTION.CLAIM, {}, CLEANER);
  await run(s, ACTION.SUBMIT_CLEAN, {}, CLEANER);
  await run(s, ACTION.PASS_INSPECTION, {}, MANAGER);
  const before = s.rooms.get('R1');
  const { room, entry } = await s.setRoomActive('R1', { active: false, reason: '装修改造' }, MANAGER);
  assert.equal(room.active, false);
  assert.equal(entry.manageAction, 'ROOM_DEACTIVATE');
  assert.equal(entry.reason, '装修改造');
  // 状态/版本/责任人不变
  assert.equal(s.rooms.get('R1').state, before.state);
  assert.equal(s.rooms.get('R1').version, before.version);
  // 停用后不能再流转
  await assert.rejects(run(s, ACTION.CHECK_IN, {}, FRONT), e => e.code === 'ROOM_INACTIVE');
  // 历史仍可查
  assert.equal(s.history('R1', 10).length, 5);
  // 启用后可继续流转，版本接着走
  await s.setRoomActive('R1', { active: true }, MANAGER);
  const v = s.rooms.get('R1').version;
  await run(s, ACTION.CHECK_IN, { expectedVersion: v }, FRONT);
  assert.equal(s.rooms.get('R1').state, STATE.IN_USE);
});

test('停用/改名/新增都进入全局动态流，与流转事件共用 seq 且断线可补齐', async () => {
  const s = freshStore();
  await run(s, ACTION.CHECK_IN, {}, FRONT); // seq 1
  const created = await s.createRoom({ id: 'R309', name: '309' }, MANAGER); // seq 2
  await s.renameRoom('R1', { name: '一号' }, MANAGER); // seq 3
  const items = s.feed({ afterSeq: 0, limit: 50 }).events;
  assert.deepEqual(items.map(i => i.seq), [1, 2, 3]);
  assert.equal(items[0].kind, 'transition');
  assert.equal(items[1].kind, 'manage');
  assert.equal(items[1].manageAction, 'ROOM_CREATE');
  assert.equal(items[2].manageAction, 'ROOM_RENAME');
  // afterSeq 缺口补齐正常
  const gap = s.feed({ afterSeq: 1, limit: 50 }).events;
  assert.deepEqual(gap.map(i => i.seq), [created.entry.seq, 3]);
});

test('包厢管理结果重启后保留（active/名称/审计条目/seq 延续）', async () => {
  const dir = tmpDir();
  t = 1_000_000_000_000;
  const s1 = new RoomStore({ dir, now: clock });
  s1.rooms.set('R1', { id: 'R1', name: 'R1', active: true });
  s1.events.set('R1', []);
  s1._rebuildRoomFromEvents('R1');
  await s1.setRoomActive('R1', { active: false, reason: '装修' }, MANAGER);
  const maxSeq = s1.seqMax;

  const s2 = new RoomStore({ dir, now: clock });
  assert.equal(s2.rooms.get('R1').active, false);
  assert.equal(s2.roomEntries.length, 1);
  assert.equal(s2.seqMax, maxSeq);
  assert.equal(s2.feed({ limit: 10 }).events.at(-1).manageAction, 'ROOM_DEACTIVATE');
});
