// ---- 包厢管理 ----

async function api(base, method, urlPath, body, headers) {
  const res = await fetch(`${base}${urlPath}`, {
    method,
    headers: { 'Content-Type': 'application/json', ...headers },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  return { status: res.status, data };
}

test('包厢管理：经理新增包厢立即生效；非经理 403', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // 前台/保洁无权
    assert.equal((await api(base, 'POST', '/api/rooms', { id: 'R309', name: '309' }, {
      'X-Role': 'FRONT', 'X-User-Id': 'u-f', 'X-User-Name': L('前台-小林'),
    })).status, 403);

    const r = await api(base, 'POST', '/api/rooms', { name: '309（中包）' }, MANAGER_HEADERS);
    assert.equal(r.status, 200);
    assert.match(r.data.room.id, /^R\d+$/);
    assert.equal(r.data.room.state, 'OPEN');
    assert.equal(r.data.room.version, 0);
    assert.equal(r.data.entry.manageAction, 'ROOM_CREATE');
    const newId = r.data.room.id;

    const rooms = await (await fetch(`${base}/api/rooms`)).json();
    const found = rooms.rooms.find(x => x.id === newId);
    assert.ok(found && found.active === true);

    // 重复编号 409、非法编号 400
    assert.equal((await api(base, 'POST', '/api/rooms', { id: newId, name: 'x' }, MANAGER_HEADERS)).status, 409);
    assert.equal((await api(base, 'POST', '/api/rooms', { id: 'BAD', name: 'x' }, MANAGER_HEADERS)).status, 400);
  } finally {
    child.kill();
  }
});

test('改名：动态/后续事件用新名，历史记录保留旧名快照', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // R303 播种事件发生时名为“303（大包）”
    const before = await (await fetch(`${base}/api/rooms/R303/history?limit=10`)).json();
    assert.equal(before.events[0].roomName, '303（大包）');

    const r = await api(base, 'PATCH', '/api/rooms/R303/name', { name: '303（豪华大包）' }, MANAGER_HEADERS);
    assert.equal(r.status, 200);
    // 状态/版本/责任人不受影响
    const rooms = await (await fetch(`${base}/api/rooms`)).json();
    const r303 = rooms.rooms.find(x => x.id === 'R303');
    assert.equal(r303.name, '303（豪华大包）');
    assert.equal(r303.state, 'TO_CLEAN');
    assert.equal(r303.version, 1);

    // 之后的流转事件带新名
    await postTransition(base, 'R303', { action: 'CLAIM', expectedVersion: 1 }, {
      'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐'),
    });
    const hist = await (await fetch(`${base}/api/rooms/R303/history?limit=10`)).json();
    assert.equal(hist.events[0].action, 'CLAIM');
    assert.equal(hist.events[0].roomName, '303（豪华大包）');
    assert.equal(hist.events[1].roomName, '303（大包）'); // 旧事件不被追溯

    // 非经理改名 403；改成同名 400
    assert.equal((await api(base, 'PATCH', '/api/rooms/R303/name', { name: 'z' }, {
      'X-Role': 'FRONT', 'X-User-Id': 'u-f', 'X-User-Name': L('前台-小林'),
    })).status, 403);
    assert.equal((await api(base, 'PATCH', '/api/rooms/R303/name', { name: '303（豪华大包）' }, MANAGER_HEADERS)).status, 400);
  } finally {
    child.kill();
  }
});

test('停用：仅 OPEN 可停用；停用后看板过滤、流转拒绝、历史仍可查；启用恢复', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // 非 OPEN（R303 待清洁）停用被拒 409
    assert.equal((await api(base, 'PATCH', '/api/rooms/R303/active', { active: false, reason: '装修' }, MANAGER_HEADERS)).status, 409);

    // 新建空闲包厢后停用
    const created = await api(base, 'POST', '/api/rooms', { id: 'R309', name: '309' }, MANAGER_HEADERS);
    assert.equal(created.status, 200);
    const off = await api(base, 'PATCH', '/api/rooms/R309/active', { active: false, reason: '装修改造' }, MANAGER_HEADERS);
    assert.equal(off.status, 200);
    assert.equal(off.data.room.active, false);
    assert.equal(off.data.entry.reason, '装修改造');

    // 停用包厢流转被拒（即使版本“正确”）
    const blocked = await api(base, 'POST', '/api/rooms/R309/transitions',
      { action: 'CHECK_IN', expectedVersion: 0 }, {
        'X-Role': 'FRONT', 'X-User-Id': 'u-f', 'X-User-Name': L('前台-小林'),
      });
    assert.equal(blocked.status, 400);
    assert.equal(blocked.data.code, 'ROOM_INACTIVE');

    // 历史仍可查（新包厢只有新增审计，没有流转记录；用有记录的 R303 类比，
    // 这里验证停用包厢本身的 history 接口可用）
    const hist = await fetch(`${base}/api/rooms/R309/history?limit=10`);
    assert.equal(hist.status, 200);

    // 动态流包含停用审计条目
    const feed = await (await fetch(`${base}/api/feed?limit=50`)).json();
    const deact = feed.events.find(e => e.kind === 'manage' && e.manageAction === 'ROOM_DEACTIVATE');
    assert.ok(deact && deact.roomId === 'R309' && deact.reason === '装修改造');

    // 重新启用后可流转
    const on = await api(base, 'PATCH', '/api/rooms/R309/active', { active: true }, MANAGER_HEADERS);
    assert.equal(on.status, 200);
    await postTransition(base, 'R309', { action: 'CHECK_IN', expectedVersion: 0 }, {
      'X-Role': 'FRONT', 'X-User-Id': 'u-f', 'X-User-Name': L('前台-小林'),
    });
  } finally {
    child.kill();
  }
});
EOF
