// 新增包厢：初始 OPEN / version 0 / 无责任人；编号可自动生成
async createRoom(op, operator) {
  return this._withLock(`__room__:${op.id || 'auto'}`, () => {
    this._requireManager(operator);
    const name = RoomStore.normalizeName(op.name);
    let id = String(op.id || '').trim().toUpperCase();
    if (!id) id = this._nextRoomId();
    if (!RoomStore.isValidRoomId(id)) {
      throw new DomainError('包厢编号需为 R 开头加 2~6 位数字（如 R309）');
    }
    if (this.rooms.has(id)) throw new DomainError(`包厢编号 ${id} 已存在`, 409, 'ROOM_EXISTS');
    const room = { id, name, active: true, state: STATE.OPEN, version: 0, responsible: null, since: null };
    this.rooms.set(id, { ...room });
    this.events.set(id, []);
    const entry = this._addRoomEntry(MANAGE.CREATE, room, operator, {
      fromName: null, toName: name, reason: null,
    });
    this._persist();
    this._emit('room', { entry, room: { ...room } });
    return { room: { ...room }, entry };
  });
}

// 自动编号：取现有 R数字 中的最大值 +1
_nextRoomId() {
  let max = 300;
  for (const id of this.rooms.keys()) {
    const m = /^R(\d+)$/.exec(id);
    if (m) max = Math.max(max, Number(m[1]));
  }
  return `R${max + 1}`;
}

// 改名：只改当前展示名；历史事件保留各自的 roomName 快照
async renameRoom(roomId, op, operator) {
  return this._withLock(roomId, () => {
    this._requireManager(operator);
    const room = this.rooms.get(roomId);
    if (!room) throw new DomainError('包厢不存在', 404, 'NOT_FOUND');
    const name = RoomStore.normalizeName(op.name);
    if (name === room.name) throw new DomainError('新名称与当前名称相同');
    const fromName = room.name;
    room.name = name;
    const entry = this._addRoomEntry(MANAGE.RENAME, room, operator, {
      fromName, toName: name, reason: null,
    });
    this._persist();
    this._emit('room', { entry, room: { ...room } });
    return { room: { ...room }, entry };
  });
}

// 停用/启用：停用只允许空闲（OPEN）包厢，避免挂在住客/清洁/检查单
async setRoomActive(roomId, op, operator) {
  return this._withLock(roomId, () => {
    this._requireManager(operator);
    const room = this.rooms.get(roomId);
    if (!room) throw new DomainError('包厢不存在', 404, 'NOT_FOUND');
    const active = op.active !== false;
    if (active === room.active) {
      throw new DomainError(active ? '包厢本就在营' : '包厢已停用');
    }
    let reason = null;
    if (!active) {
      if (room.state !== STATE.OPEN) {
        throw new DomainError(
          `包厢当前为「${STATE_LABEL[room.state]}」，需退房并完成清洁检查、回到可开放后才能停用`,
          409, 'ROOM_BUSY',
        );
      }
      reason = op.reason ? String(op.reason).trim() : null;
    }
    room.active = active;
    const entry = this._addRoomEntry(
      active ? MANAGE.ACTIVATE : MANAGE.DEACTIVATE,
      room, operator,
      { fromName: room.name, toName: room.name, reason },
    );
    // 停用清掉残留预警；启用后 tick 按当前状态重新评估
    for (const key of [...this.alerts.keys()]) {
      if (key.startsWith(`${roomId}:`)) this.alerts.delete(key);
    }
    this._persist();
    this._emit('room', { entry, room: { ...room } });
    if (active) this._evaluateAlerts(false);
    return { room: { ...room }, entry };
  });
}

