  // 同一幂等键的重试也必须返回第一次的结果，而不是报 ROOM_INACTIVE
  if (idemKey) {
    const cached = this.idempotency.get(idemKey);
    if (cached && cached.roomId === roomId) {
      return { event: cached.event, duplicated: true };
    }
  }

  if (room.active === false) {
    throw new DomainError(`「${room.name}」已停用（装修改造），不能交接流转`, 400, 'ROOM_INACTIVE');
  }
  const op = RoomStore.normalizeOperator(operator);
  const { action, expectedVersion } = data;
  let reason = null;

  if (!ACTION[action]) throw new DomainError(`未知动作: ${action}`);
  if (!ACTION_ROLES[action].includes(op.role)) {
    throw new DomainError(`${ROLE_LABEL[op.role]}无权执行「${ACTION_LABEL[action]}」`, 403, 'FORBIDDEN');
  }
  if (typeof expectedVersion !== 'number') {
    throw new DomainError('缺少 expectedVersion', 409, 'VERSION_CONFLICT');
  }
  if (expectedVersion !== room.version) {
    throw new DomainError(
      `状态已被其他人更新（你基于 v${expectedVersion}，当前 v${room.version}），请刷新后重试`,
      409, 'VERSION_CONFLICT',
    );
  }
  if (REASON_REQUIRED.has(action)) {
    reason = RoomStore.cleanReason(data.reason, { required: true });
  } else {
    reason = RoomStore.cleanReason(data.reason);
  }

