cat >> /workspace/mac-001/test/server.feed.test.js << 'EOF'

test('幂等：房间停用后同一幂等键重试仍返回第一次结果（而非 ROOM_INACTIVE）', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // 新建空闲包厢并完成一次带幂等键的开房
    const created = await api(base, 'POST', '/api/rooms', { id: 'R309', name: '309' }, MANAGER_HEADERS);
    assert.equal(created.status, 200);
    const front = {
      'X-Role': 'FRONT', 'X-User-Id': 'u-f', 'X-User-Name': L('前台-阿珍'),
    };
    const first = await postTransition(base, 'R309', {
      action: 'CHECK_IN', expectedVersion: 0, idempotencyKey: 'idem-room-off',
    }, front);
    assert.equal(first.duplicated, false);

    // 把它走完流程回到 OPEN 再停用
    await postTransition(base, 'R309', { action: 'CHECK_OUT', expectedVersion: 1 }, front);
    await postTransition(base, 'R309', { action: 'CLAIM', expectedVersion: 2 }, {
      'X-Role': 'CLEANER', 'X-User-Id': 'u-c', 'X-User-Name': L('保洁-王姐'),
    });
    await postTransition(base, 'R309', { action: 'SUBMIT_CLEAN', expectedVersion: 3 }, {
      'X-Role': 'CLEANER', 'X-User-Id': 'u-c', 'X-User-Name': L('保洁-王姐'),
    });
    await postTransition(base, 'R309', { action: 'PASS_INSPECTION', expectedVersion: 4 }, MANAGER_HEADERS);
    const off = await api(base, 'PATCH', '/api/rooms/R309/active',
      { active: false, reason: '装修' }, MANAGER_HEADERS);
    assert.equal(off.status, 200);

    // 停用后用同一个幂等键重试：必须返回首次结果，duplicated=true，而非报错
    const replay = await postTransition(base, 'R309', {
      action: 'CHECK_IN', expectedVersion: 0, idempotencyKey: 'idem-room-off',
    }, front);
    assert.equal(replay.duplicated, true);
    assert.equal(replay.event.seq, first.event.seq);
    assert.equal(replay.event.id, first.event.id);

    // 新的（不同幂等键）流转仍应被停用拦截
    const blocked = await api(base, 'POST', '/api/rooms/R309/transitions',
      { action: 'CHECK_IN', expectedVersion: 5 }, front);
    assert.equal(blocked.status, 400);
    assert.equal(blocked.data.code, 'ROOM_INACTIVE');
  } finally {
    child.kill();
  }
});
EOF
node --test test/server.feed.test.js 2>&1 | grep -E "^(ok|not ok|# (tests|pass|fail))" | tail -8

cat >> /workspace/mac-001/test/server.feed.test.js << 'EOF'

test('安全：姓名/包厢名/原因里的脚本与控制字符在入库时被清洗/转义', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // 经理用带脚本的包厢名新建/改名
    const xssName = '309<img src=x onerror=alert(1)>';
    const created = await api(base, 'POST', '/api/rooms', { id: 'R309', name: xssName }, MANAGER_HEADERS);
    assert.equal(created.status, 200);
    // 名称原样保留（标签是数据），前端负责转义；控制字符被剔除
    assert.equal(created.data.room.name, xssName);

    // 保洁姓名含 <script>，作为操作人发生一次流转（R303 待清洁 → 接单）
    const evilName = '保洁<script>alert("x")</script>';
    await postTransition(base, 'R303', { action: 'CLAIM', expectedVersion: 1 }, {
      'X-Role': 'CLEANER', 'X-User-Id': L('u-evil'), 'X-User-Name': L(evilName),
    });
    const hist = await (await fetch(`${base}/api/rooms/R303/history?limit=5`)).json();
    const claim = hist.events.find(e => e.action === 'CLAIM');
    assert.ok(claim);
    assert.equal(claim.operatorName, evilName); // 服务端原样存储，不解释执行

    // 原因里塞脚本（检查不通过强制原因）：先报检
    await postTransition(base, 'R303', { action: 'SUBMIT_CLEAN', expectedVersion: 2 }, {
      'X-Role': 'CLEANER', 'X-User-Id': L('u-evil'), 'X-User-Name': L(evilName),
    });
    const reason = '"><img src=x onerror=alert(2)>';
    await postTransition(base, 'R303', {
      action: 'REJECT_INSPECTION', expectedVersion: 3, reason,
    }, MANAGER_HEADERS);
    const hist2 = await (await fetch(`${base}/api/rooms/R303/history?limit=5`)).json();
    assert.equal(hist2.events.find(e => e.action === 'REJECT_INSPECTION').reason, reason);

    // /api/feed 原样返回（Content-Type 是 JSON，不会作为 HTML 执行；前端转义渲染）
    const feed = await (await fetch(`${base}/api/feed?limit=50`)).json();
    const evil = feed.events.find(e => e.action === 'REJECT_INSPECTION');
    assert.equal(evil.reason, reason);
    const ctype = (await fetch(`${base}/api/feed?limit=1`)).headers.get('content-type');
    assert.match(ctype, /^application\/json/);

    // 控制字符（如 null/换行）从自由文本中剔除
    const ctrlName = '王�姐\n';
    await postTransition(base, 'R303', { action: 'SUBMIT_CLEAN', expectedVersion: 4 }, {
      'X-Role': 'CLEANER', 'X-User-Id': L('u-c2'), 'X-User-Name': L(ctrlName),
    });
    const hist3 = await (await fetch(`${base}/api/rooms/R303/history?limit=5`)).json();
    const byC2 = hist3.events.find(e => e.operatorId === 'u-c2');
    assert.equal(byC2.operatorName, '王姐');
  } finally {
    child.kill();
  }
});
EOF
