test('安全：脚本片段作为数据原样存储，控制字符在入库时被剔除', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // 经理用带脚本的包厢名新建（标签是数据，不应被解释执行；前端渲染时转义）
    const xssName = '309<img src=x onerror=alert(1)>';
    const created = await api(base, 'POST', '/api/rooms', { id: 'R309', name: xssName }, MANAGER_HEADERS);
    assert.equal(created.status, 200);
    assert.equal(created.data.room.name, xssName);

    // 保洁姓名含 <script>，作为操作人发生一次流转
    const evilName = '保洁<script>alert("x")</script>';
    await postTransition(base, 'R303', { action: 'CLAIM', expectedVersion: 1 }, {
      'X-Role': 'CLEANER', 'X-User-Id': L('u-evil'), 'X-User-Name': L(evilName),
    });
    let hist = await (await fetch(`${base}/api/rooms/R303/history?limit=5`)).json();
    assert.equal(hist.events.find(e => e.action === 'CLAIM').operatorName, evilName);

    // 原因里塞脚本：报检 → 驳回（强制原因）
    await postTransition(base, 'R303', { action: 'SUBMIT_CLEAN', expectedVersion: 2 }, {
      'X-Role': 'CLEANER', 'X-User-Id': L('u-evil'), 'X-User-Name': L(evilName),
    });
    const reason = '"><img src=x onerror=alert(2)>';
    await postTransition(base, 'R303', {
      action: 'REJECT_INSPECTION', expectedVersion: 3, reason,
    }, MANAGER_HEADERS);
    hist = await (await fetch(`${base}/api/rooms/R303/history?limit=5`)).json();
    assert.equal(hist.events.find(e => e.action === 'REJECT_INSPECTION').reason, reason);

    // 动态接口是 JSON（不作为 HTML 执行），原样返回
    const ctype = (await fetch(`${base}/api/feed?limit=1`)).headers.get('content-type');
    assert.match(ctype, /^application\/json/);
    const feed = await (await fetch(`${base}/api/feed?limit=50`)).json();
    assert.equal(feed.events.find(e => e.action === 'REJECT_INSPECTION').reason, reason);

    // 自由文本中的控制字符（null/换行）在入库前被剔除
    const ctrlName = `王${String.fromCharCode(0)}姐\n`;
    await postTransition(base, 'R303', { action: 'SUBMIT_CLEAN', expectedVersion: 4 }, {
      'X-Role': 'CLEANER', 'X-User-Id': L('u-c2'), 'X-User-Name': L(ctrlName),
    });
    hist = await (await fetch(`${base}/api/rooms/R303/history?limit=5`)).json();
    assert.equal(hist.events.find(e => e.operatorId === 'u-c2').operatorName, '王姐');
  } finally {
    child.kill();
  }
});

