input.content:
// 前端转义规则的回归测试：所有进入 innerHTML 的用户可控文本必须经 escapeHtml。
// 这里直接校验 public/index.html 中渲染函数对姓名/包厢名/原因的处理方式，
// 防止后续有人改回裸插值导致存储型 XSS。
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

const html = fs.readFileSync(path.join(import.meta.dirname, '..', 'public', 'index.html'), 'utf8');

// 与前端一致的转义实现，验证其对常见注入向量有效
function escapeHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

const PAYLOADS = [
  '<img src=x onerror=alert(1)>',
  '<script>alert("x")</script>',
  '"><svg onload=alert(2)>',
  " javascript:alert(3)",
  "' onmouseover='alert(4)",
];

test('escapeHtml 让脚本/属性注入向量失去可执行性', () => {
  for (const p of PAYLOADS) {
    const out = escapeHtml(p);
    assert.ok(!/<(?!\/?b|img|svg)/.test(out) === false || !out.includes('<script'), out);
    assert.ok(!out.includes('<'), `尖括号必须被转义: ${out}`);
    assert.ok(!out.includes('>'), `尖括号必须被转义: ${out}`);
    assert.ok(!/[="']\s*on\w+=/i.test(out) || !out.includes('"'), `引号必须被转义: ${out}`);
    assert.ok(out.includes('&lt;') && out.includes('&gt;'));
  }
});

test('渲染处：交接记录表的姓名/责任人/原因都经过 escapeHtml', () => {
  const block = html.slice(html.indexOf('async function showHistory'), html.indexOf('// ---- toast'));
  assert.match(block, /escapeHtml\(ev\.operatorName\)/);
  assert.match(block, /escapeHtml\(ev\.toResponsible/);
  assert.match(block, /escapeHtml\(ev\.reason\)/);
  // 不能出现裸插值
  assert.ok(!/\$\{ev\.operatorName\}/.test(block));
  assert.ok(!/\$\{ev\.toResponsible\}/.test(block));
});

test('渲染处：超时提醒的包厢名/责任人经过 escapeHtml', () => {
  const block = html.slice(html.indexOf('function renderAlerts'), html.indexOf('function stateLabel'));
  assert.match(block, /escapeHtml\(a\.roomName\)/);
  assert.match(block, /escapeHtml\(a\.responsible\?\.name\)/);
  assert.ok(!/\$\{a\.roomName\}/.test(block));
});

test('渲染处：卡片/停用区/动态栏/管理条目的用户文本均经过 escapeHtml', () => {
  for (const needle of [
    'escapeHtml(room.name)',
