/**
 * 交接动态（跨包厢全局事件流）
 * - 不传 afterSeq：返回最近 limit 条（升序），用于看板首屏
 * - 传 afterSeq：从该游标之后“最早的一页”开始按 seq 升序返回，
 *   hasMore 时 nextCursor 指向本页最后一条，客户端逐页向后拿，
 *   天然按发生顺序到达，且不会因前端裁剪旧动态而翻页死循环
 */
// 交接动态的统一来源：状态流转 + 包厢管理动作，按全局 seq 排序
_feedItems() {
  const all = [];
  for (const evs of this.events.values()) {
    for (const ev of evs) all.push({ kind: 'transition', ...ev });
  }
  for (const en of this.roomEntries) all.push({ kind: 'manage', ...en });
  all.sort((a, b) => a.seq - b.seq);
  return all;
}

feed({ afterSeq = null, limit = 50 } = {}) {
  limit = clampLimit(limit);
  const all = this._feedItems();
  const latestSeq = this.seqMax;
  if (afterSeq == null) {
    return { events: all.slice(-limit), latestSeq, hasMore: false, nextCursor: null };
  }
  const seq = Number(afterSeq);
  if (!Number.isFinite(seq)) throw new DomainError('afterSeq 参数无效');
  const newer = all.filter((ev) => ev.seq > seq);
  const page = newer.slice(0, limit);
  const hasMore = newer.length > page.length;
  return {
    events: page,
    latestSeq,
    hasMore,
    nextCursor: hasMore && page.length ? page[page.length - 1].seq : null,
  };
}

