/**
 * 交接动态（跨包厢全局事件流：状态流转 + 包厢管理动作），统一按全局 seq 升序。
 *
 * 游标（互斥）：
 * - 都不传：返回最近 limit 条（看板首屏 / 切换筛选）
 * - afterSeq：返回该游标之后“最早的一页”，用于断线按发生顺序补齐（向前翻）
 * - beforeSeq：返回该游标之前“最晚的一页”（升序返回），用于动态栏往更早翻看
 *
 * 筛选（roomId / action / operator）在“筛选后的子集”内独立分页，
 * 因此筛选与翻页组合时不会重复也不会漏；返回的 nextCursor 是该筛选子集中的下一个游标。
 * kind=manage 的管理条目没有 action，action 筛选只作用于流转事件。
 */
feed({ afterSeq = null, beforeSeq = null, limit = 50, roomId = null, action = null, operator = null } = {}) {
  limit = clampLimit(limit);
  if (afterSeq != null && beforeSeq != null) {
    throw new DomainError('afterSeq 与 beforeSeq 不能同时使用');
  }
  if (roomId != null && !this.rooms.has(roomId)) {
    throw new DomainError('包厢不存在', 404, 'NOT_FOUND');
  }
  let acts = null;
  if (action) {
    const list = String(action).split(',').map((s) => s.trim()).filter(Boolean);
    for (const a of list) if (!ACTION[a]) throw new DomainError(`未知动作筛选: ${a}`);
    acts = new Set(list);
  }
  const op = cleanText(operator);
  if (op.length > 30) throw new DomainError('操作人筛选过长');

  const all = this._feedItems();
  const match = (ev) => {
    if (roomId != null && ev.roomId !== roomId) return false;
    if (acts) {
      if (ev.kind !== 'transition' || !acts.has(ev.action)) return false;
    }
    if (op) {
      const hay = `${ev.operatorName || ''} ${ev.operatorId || ''}`;
      if (!hay.toLowerCase().includes(op.toLowerCase())) return false;
    }
    return true;
  };
  const matched = all.filter(match);
  const latestSeq = this.seqMax;

  if (afterSeq == null && beforeSeq == null) {
    const page = matched.slice(-limit);
    return {
      events: page,
      latestSeq,
      hasMore: matched.length > page.length,
      nextCursor: hasOlder(matched, page) ? page[0].seq : null,
    };
  }

  if (afterSeq != null) {
    const seq = Number(afterSeq);
    if (!Number.isFinite(seq)) throw new DomainError('afterSeq 参数无效');
    const newer = matched.filter((ev) => ev.seq > seq);
    const page = newer.slice(0, limit);
    const hasMore = newer.length > page.length;
    return {
      events: page,
      latestSeq,
      hasMore,
      nextCursor: hasMore && page.length ? page[page.length - 1].seq : null,
    };
  }

  // beforeSeq：游标之前更早的事件，取“最晚的一页”，仍按升序返回（渲染时倒序）
  const seq = Number(beforeSeq);
  if (!Number.isFinite(seq)) throw new DomainError('beforeSeq 参数无效');
  const older = matched.filter((ev) => ev.seq < seq);
  const page = older.slice(-limit);
  const hasMore = older.length > page.length;
  return {
    events: page,
    latestSeq,
    hasMore,
    nextCursor: hasMore && page.length ? page[0].seq : null,
  };
}

