/**
 * 单包厢交接记录（流转事件，不含包厢管理动作），按 seq 升序存放。
 * 默认（beforeSeq == null）返回最近 limit 条，升序返回；
 * 传 beforeSeq 时返回该游标之前“最晚的一页”（升序），用于弹窗向更早翻页。
 * 返回 { events, hasMore, nextCursor }。
 */
history(roomId, { limit = 50, beforeSeq = null } = {}) {
  const room = this.rooms.get(roomId);
  if (!room) throw new DomainError('包厢不存在', 404, 'NOT_FOUND');
  const n = clampLimit(limit);
  const evs = (this.events.get(roomId) || []).slice().sort((a, b) => a.seq - b.seq);
  let base = evs;
  if (beforeSeq != null) {
    const seq = Number(beforeSeq);
    if (!Number.isFinite(seq)) throw new DomainError('beforeSeq 参数无效');
    base = evs.filter((e) => e.seq < seq);
  }
  const page = base.slice(-n);
  const hasMore = base.length > page.length;
  return {
    events: page,
    hasMore,
    nextCursor: hasMore && page.length ? page[0].seq : null,
  };
}

