test('交接动态：首屏取最近 N 条，afterSeq 从最早缺口页按顺序翻页', async () => {
  const s = freshStore();
  for (const id of ['R2', 'R3']) {
    s.rooms.set(id, { id, name: id });
    s.events.set(id, []);
    s._rebuildRoomFromEvents(id);
  }
  await run(s, ACTION.CHECK_IN, { roomId: 'R1' }, FRONT);
  await run(s, ACTION.CHECK_IN, { roomId: 'R2' }, FRONT);
  await run(s, ACTION.CHECK_IN, { roomId: 'R3' }, FRONT);

  // 首屏最近 2 条（升序）
  const first = s.feed({ limit: 2 });
  assert.deepEqual(first.events.map((e) => e.seq), [2, 3]);
  assert.equal(first.latestSeq, 3);
  assert.equal(first.hasMore, false);

  // 只收到 seq 1 后断线，重连补齐 2、3
  const gap = s.feed({ afterSeq: 1, limit: 50 });
  assert.deepEqual(gap.events.map((e) => e.seq), [2, 3]);
  assert.equal(gap.hasMore, false);
  assert.equal(gap.nextCursor, null);

  // 缺口过大分页：每页 1 条，从最早的开始向后翻
  let p = s.feed({ afterSeq: 0, limit: 1 });
  assert.deepEqual(p.events.map((e) => e.seq), [1]);
  assert.equal(p.hasMore, true);
  assert.equal(p.nextCursor, 1);
  p = s.feed({ afterSeq: p.nextCursor, limit: 1 });
  assert.deepEqual(p.events.map((e) => e.seq), [2]);
  assert.equal(p.nextCursor, 2);
  p = s.feed({ afterSeq: p.nextCursor, limit: 1 });
  assert.deepEqual(p.events.map((e) => e.seq), [3]);
  assert.equal(p.hasMore, false);
  assert.equal(p.nextCursor, null);
});

