// ---- 交接动态：筛选与向后翻页 ----

test('feed 按包厢筛选，且筛选子集内独立分页不重不漏', async () => {
  const s = freshStore();
  s.rooms.set('R2', { id: 'R2', name: 'R2', active: true });
  s.events.set('R2', []);
  s._rebuildRoomFromEvents('R2');
  await run(s, ACTION.CHECK_IN, { roomId: 'R1' }, FRONT); // seq1 R1
  await run(s, ACTION.CHECK_IN, { roomId: 'R2' }, FRONT); // seq2 R2
  await run(s, ACTION.CHECK_OUT, { roomId: 'R1' }, FRONT); // seq3 R1
  await run(s, ACTION.CHECK_OUT, { roomId: 'R2' }, FRONT); // seq4 R2

  const f = s.feed({ roomId: 'R1', limit: 50 });
  assert.deepEqual(f.events.map((e) => e.seq), [1, 3]);
  assert.equal(f.hasMore, false);

  // 筛选 + beforeSeq 在子集内分页（造更多 R1 事件，每页 1 条）
  await run(s, ACTION.CLAIM, { roomId: 'R1' }, CLEANER); // seq5 R1
  let p = s.feed({ roomId: 'R1', limit: 1 });
  assert.deepEqual(p.events.map((e) => e.seq), [5]);
  assert.equal(p.hasMore, true);
  p = s.feed({ roomId: 'R1', beforeSeq: p.nextCursor, limit: 1 });
  assert.deepEqual(p.events.map((e) => e.seq), [3]);
  p = s.feed({ roomId: 'R1', beforeSeq: p.nextCursor, limit: 1 });
  assert.deepEqual(p.events.map((e) => e.seq), [1]);
  assert.equal(p.hasMore, false);
  // 不存在的包厢 404
  assert.throws(() => s.feed({ roomId: 'NOPE' }), e => e.status === 404);
});

test('feed 按动作筛选（含管理动作，逗号分隔多个）', async () => {
  const s = freshStore();
  await run(s, ACTION.CHECK_IN, {}, FRONT);
  await run(s, ACTION.CHECK_OUT, {}, FRONT);
  await s.createRoom({ id: 'R309', name: '309' }, MANAGER);
  await s.renameRoom('R309', { name: '309改' }, MANAGER);

  const checks = s.feed({ action: ACTION.CHECK_IN, limit: 50 }).events;
  assert.deepEqual(checks.map((e) => e.seq), [1]);
  // 多个动作
  const multi = s.feed({ action: `${ACTION.CHECK_OUT},${ACTION.CHECK_IN}`, limit: 50 }).events;
  assert.deepEqual(multi.map((e) => e.seq), [1, 2]);
  // 管理动作
  const mgmt = s.feed({ action: 'ROOM_RENAME', limit: 50 }).events;
  assert.equal(mgmt.length, 1);
  assert.equal(mgmt[0].kind, 'manage');
  // 非法动作 400
  assert.throws(() => s.feed({ action: 'HACK' }), e => e.status === 400);
});

test('feed 按操作人姓名/id 子串筛选（大小写不敏感）', async () => {
  const s = freshStore();
  await run(s, ACTION.CHECK_IN, {}, FRONT);
  await run(s, ACTION.CHECK_OUT, {}, FRONT);
  await run(s, ACTION.CLAIM, {}, CLEANER);

  assert.deepEqual(s.feed({ operator: '小林', limit: 50 }).events.map((e) => e.seq), [1, 2]);
  assert.deepEqual(s.feed({ operator: '王姐', limit: 50 }).events.map((e) => e.seq), [3]);
  assert.deepEqual(s.feed({ operator: 'u-clean', limit: 50 }).events.map((e) => e.seq), [3]);
  assert.deepEqual(s.feed({ operator: '不存在', limit: 50 }).events, []);
});

test('feed：afterSeq 与 beforeSeq 同时传报错；非法游标报错', () => {
  const s = freshStore();
  assert.throws(() => s.feed({ afterSeq: 1, beforeSeq: 2 }), /不能同时/);
  assert.throws(() => s.feed({ afterSeq: 'x' }), e => e.status === 400);
  assert.throws(() => s.feed({ beforeSeq: 'x' }), e => e.status === 400);
});

test('history：beforeSeq 向更早翻页，按 seq 不重不漏', async () => {
  const s = freshStore();
  await run(s, ACTION.CHECK_IN, {}, FRONT);
  await run(s, ACTION.CHECK_OUT, {}, FRONT);
  await run(s, ACTION.CLAIM, {}, CLEANER);
  // 最近一页 2 条（升序）
  let h = s.history('R1', { limit: 2 });
  assert.deepEqual(h.events.map((e) => e.seq), [2, 3]);
  assert.equal(h.hasMore, true);
  assert.equal(h.nextCursor, 2);
  // 更早一页
  h = s.history('R1', { limit: 2, beforeSeq: h.nextCursor });
  assert.deepEqual(h.events.map((e) => e.seq), [1]);
  assert.equal(h.hasMore, false);
  assert.equal(h.nextCursor, null);
});
TESTEOF
node --test test/store.test.js 2>&1 | grep -E "^# (tests|pass|fail)|not ok"

