let state = null;
const FEED_PAGE = 30;        // 动态每次加载条数（首屏/翻页同页大小）
const FEED_KEEP = 1000;      // 本地最多缓存条数（足够交接班复盘）
const feedItems = [];        // 已加载的动态（当前筛选子集），按 seq 倒序
const seenSeqs = new Set();
let lastSeq = 0;             // 已从实时通道收到的全局最大 seq（断线补齐游标，与筛选无关）
let everConnected = false;
// 动态筛选：空串表示不过滤
const feedFilter = { roomId: '', action: '', operator: '' };
let feedHasMore = false;     // 当前筛选下是否还有更早的事件
let feedOlderCursor = null;  // 向更早翻页的游标
let feedLoading = false;

function currentFilters() {
  return {
    roomId: document.getElementById('feedRoom').value || '',
    action: document.getElementById('feedAction').value || '',
    operator: document.getElementById('feedOperator').value.trim(),
  };
}
function filtersActive() {
  const f = currentFilters();
  return !!(f.roomId || f.action || f.operator);
}

// 清空已加载动态（切换筛选 / 重新首屏时）
function resetFeed() {
  feedItems.length = 0;
  seenSeqs.clear();
  feedHasMore = false;
  feedOlderCursor = null;
}

// 合并动态页：同一 seq 只出现一次，统一按 seq 倒序排列
function mergeFeedEvents(events) {
  let added = 0;
  for (const ev of events || []) {
    if (!ev || !Number.isInteger(ev.seq) || seenSeqs.has(ev.seq)) continue;
    seenSeqs.add(ev.seq);
    feedItems.push(ev);
    added++;
  }
  if (added) {
    feedItems.sort((a, b) => b.seq - a.seq);
    for (const ev of feedItems.splice(FEED_KEEP)) seenSeqs.delete(ev.seq);
    if (state) renderFeed();
  }
  return added;
}

function feedQuery(extra = {}) {
  const q = new URLSearchParams({ limit: FEED_PAGE });
  const f = currentFilters();
  if (f.roomId) q.set('roomId', f.roomId);
  if (f.action) q.set('action', f.action);
  if (f.operator) q.set('operator', f.operator);
  for (const [k, v] of Object.entries(extra)) if (v != null) q.set(k, v);
  return fetch(`/api/feed?${q}`).then((r) => {
    if (!r.ok) throw new Error('feed fetch failed');
    return r.json();
  });
}

// 首屏 / 切换筛选：取当前筛选子集最近一页
async function loadInitialFeed() {
  try {
    resetFeed();
    const data = await feedQuery();
    feedHasMore = data.hasMore;
    feedOlderCursor = data.nextCursor;
    mergeFeedEvents(data.events);
    updateFeedHint();
  } catch (e) { /* 拉取失败不影响实时推送，重连时还会补齐 */ }
}

// 向更早翻看：取当前最早一条之前的一页
async function loadOlderFeed() {
  if (feedLoading || !feedHasMore || feedOlderCursor == null) return;
  feedLoading = true;
  const btn = document.getElementById('feedMore');
  btn.disabled = true; btn.textContent = '加载中…';
  try {
    const data = await feedQuery({ beforeSeq: feedOlderCursor });
    feedHasMore = data.hasMore;
    feedOlderCursor = data.nextCursor;
    mergeFeedEvents(data.events);
  } catch (e) { /* 保留按钮可重试 */ } finally {
    feedLoading = false;
    btn.disabled = false;
    updateFeedHint();
  }
}

// 断线重连：只追全局缺口（不带筛选），匹配当前筛选的实时事件由同一去重逻辑落位
async function catchUpFeed() {
  try {
    let cursor = lastSeq;
    for (let guard = 0; guard < 50; guard++) {
      const q = new URLSearchParams({ limit: 50, afterSeq: cursor });
      const res = await fetch(`/api/feed?${q}`);
      if (!res.ok) break;
      const data = await res.json();
      for (const ev of data.events) lastSeq = Math.max(lastSeq, ev.seq);
      // 仅并入匹配当前筛选的事件，避免污染筛选视图
      mergeFeedEvents(data.events.filter(itemMatchesFilter));
      cursor = data.nextCursor;
      if (!data.hasMore || cursor == null) break;
    }
  } catch (e) { /* 网络仍不可用，下次重连继续补 */ }
}

// 客户端实时事件是否符合当前筛选（与服务端 match 规则一致）
function itemMatchesFilter(ev) {
  const f = currentFilters();
  if (f.roomId && ev.roomId !== f.roomId) return false;
  if (f.action) {
    const a = ev.kind === 'manage' ? ev.manageAction : ev.action;
    if (!f.action.split(',').map((s) => s.trim()).includes(a)) return false;
  }
  if (f.operator) {
    const hay = `${ev.operatorName || ''} ${ev.operatorId || ''}`.toLowerCase();
    if (!hay.includes(f.operator.toLowerCase())) return false;
  }
  return true;
}

// 实时通道（SSE）到达一条事件：更新全局水位，符合当前筛选才显示
function ingestLive(ev) {
  if (!Number.isInteger(ev.seq)) return;
  lastSeq = Math.max(lastSeq, ev.seq);
  if (itemMatchesFilter(ev)) mergeFeedEvents([ev]);
}

