function roomAlert(roomId) {
  return (state?.alerts || []).find(a => a.roomId === roomId);
}
function timerClass(room, al) {
  if (!state.sla[room.state] || !room.since) return '';
  if (al) return al.level === 'CRITICAL' ? 'critical' : 'overdue';
  const e = elapsed(room.since);
  if (e >= state.sla[room.state] * 2) return 'critical';
  if (e >= state.sla[room.state]) return 'overdue';
  return '';
}

function render() {
  if (!state) return;
  renderAlerts();
  const grid = document.getElementById('grid');
  const role = roleEl.value;
  const isManager = role === 'MANAGER';
  grid.innerHTML = '';
  // 停用包厢不出现在看板，只在底部管理区列出
  const activeRooms = state.rooms.filter(r => r.active !== false);
  for (const room of activeRooms) {
    const al = roomAlert(room.id);
    const card = document.createElement('div');
    card.className = `card s-${room.state}${al ? ' has-alert' : ''}`;
    const actions = room.allowedByRole[role] || [];
    const sla = state.sla[room.state];
    card.innerHTML = `
      <h3>${escapeHtml(room.name)}
        <span class="badge b-${room.state}">${room.stateLabel}</span>
        <span style="margin-left:auto;font-size:11px;color:var(--muted)">v${room.version}</span>
      </h3>
      <div class="meta">
        <span>当前责任人：<b>${room.responsible?.name ? escapeHtml(room.responsible.name) : '—'}</b></span>
        <span>进入状态：${room.since ? fmtClock(room.since) : '—'}</span>
        <span>停留：<span class="timer ${timerClass(room, al)}" data-since="${room.since || ''}" data-sla="${sla || ''}">
          ${room.since ? fmtDur(elapsed(room.since)) : ''}
        </span>${sla ? `（时限 ${fmtDur(sla)}）` : ''}</span>
      </div>
      <div class="actions">
        ${actions.map(a => `<button class="${ACTION_BTN_CLASS[a] || ''}" data-action="${a}">${actionLabel(a)}</button>`).join('')}
        <button class="ghost" data-history>交接记录</button>
        ${isManager ? '<button class="ghost manage" data-rename>改名</button><button class="ghost manage" data-deactivate>停用</button>' : ''}
      </div>`;
    card.querySelectorAll('[data-action]').forEach(btn => {
      btn.onclick = () => doAction(room, btn.dataset.action);
    });
    card.querySelector('[data-history]').onclick = () => showHistory(room);
    if (isManager) {
      card.querySelector('[data-rename]').onclick = () => openRename(room);
      card.querySelector('[data-deactivate]').onclick = () => openDeactivate(room);
    }
    grid.appendChild(card);
  }
  renderInactive();

