function updateFeedHint() {
  const hint = document.getElementById('feedHint');
  if (!hint) return;
  const f = currentFilters();
  if (f.roomId || f.action || f.operator) {
    const parts = [];
    if (f.roomId) parts.push(document.getElementById('feedRoom').selectedOptions[0]?.textContent || f.roomId);
    if (f.action) parts.push(actionLabel(f.action) || manageLabel(f.action) || f.action);
    if (f.operator) parts.push(`操作人含“${f.operator}”`);
    hint.innerHTML = `筛选中：<b>${escapeHtml(parts.join(' · '))}</b>；不符合筛选的实时动态不会出现，清除筛选可看全部`;
  } else {
    hint.textContent = '';
  }
}

