    more.style.display = 'none';
    updateFeedHint();
    return;
  }
  box.innerHTML = feedItems.map(item => item.kind === 'manage' ? renderManageItem(item) : `
    <div class="item">
      <div class="row1">
        <span class="who">${escapeHtml(item.operatorName)}（${roleLabel(item.operatorRole)}）→ ${escapeHtml(item.toResponsible)}</span>
        <span class="t" title="${new Date(item.at).toLocaleString('zh-CN', { hour12: false })}">${fmtClock(item.at)}</span>
      </div>
      <div class="row2">
        ${escapeHtml(feedRoomName(item))} · ${actionLabel(item.action)}
        ${item.fromState ? `${stateLabel(item.fromState)} → ` : ''}${stateLabel(item.toState)}
        ${item.reason ? ` · <span class="reason">原因：${escapeHtml(item.reason)}</span>` : ''}
        ${item.idempotencyKey && item.idempotencyKey.startsWith('idem-retry') ? ' · 重试命中' : ''}
      </div>
    </div>`).join('');
  more.style.display = feedHasMore ? '' : 'none';
  more.textContent = '加载更早的动态…';
  updateFeedHint();
}

// 筛选状态下实时事件的显示规则提示
function updateFeedHint() {
  const hint = document.getElementById('feedHint');
  if (!hint) return;
  const f = currentFilters();
  if (f.roomId || f.action || f.operator) {
    const parts = [];
    if (f.roomId) parts.push(document.getElementById('feedRoom').selectedOptions[0]?.textContent || f.roomId);
    if (f.action) parts.push(actionLabel(f.action) || manageLabel(f.action) || f.action);
    if (f.operator) parts.push(`操作人含“${f.operator}”`);
    hint.innerHTML = `筛选中：<b>${escapeHtml(parts.join(' · '))}</b>；不符合筛选的实时动态不会出现，清除筛选可看全部`;
  } else {
    hint.textContent = '';
  }
}

