// ---- toast ----
function toast(msg, kind = '') {
  const el = document.createElement('div');
  el.className = `toast ${kind}`;
  el.textContent = msg;
  document.getElementById('toasts').appendChild(el);
  setTimeout(() => { el.style.opacity = '0'; el.style.transition = 'opacity .3s'; setTimeout(() => el.remove(), 300); }, 3600);
}

// 倒计时每秒刷新（纯前端展示，不改变状态）
setInterval(() => {
  document.querySelectorAll('.timer[data-since]').forEach(el => {
    const since = el.dataset.since;
    if (since) el.textContent = fmtDur(elapsed(since));
  });
}, 1000);

