// 交接记录弹窗：服务端分页，向更早翻页不重不漏
const historyState = { roomId: null, events: [], hasMore: false, cursor: null, loading: false };
function historyRow(ev) {
  return `
    <tr>
      <td>${new Date(ev.at).toLocaleString('zh-CN', { hour12: false })}</td>
      <td>${ev.actionLabel}</td>
      <td>${ev.fromStateLabel ? ev.fromStateLabel + ' → ' : ''}${ev.toStateLabel}<br>
        <span style="color:var(--muted)">v${ev.version}</span></td>
      <td>${escapeHtml(ev.operatorName)}<br><span style="color:var(--muted)">${ev.operatorRoleLabel}</span></td>
      <td>${escapeHtml(ev.toResponsible || '')}</td>
      <td class="reason">${ev.reason ? escapeHtml(ev.reason) : '—'}</td>
    </tr>`;
}
function renderHistory() {
  const body = document.getElementById('historyBody');
  body.innerHTML = historyState.events.map(historyRow).join('')
    || '<tr><td colspan="6" style="color:var(--muted)">暂无记录</td></tr>';
  const more = document.getElementById('historyMore');
  more.style.display = historyState.hasMore ? '' : 'none';
  more.disabled = historyState.loading;
  more.textContent = historyState.loading ? '加载中…' : '加载更早记录…';
}
async function showHistory(room) {
  historyState.roomId = room.id;
  historyState.events = [];
  historyState.loading = true;
  document.getElementById('historyTitle').textContent = `${room.name} · 交接记录`;
  document.getElementById('historyModal').classList.add('show');
  renderHistory();
  try {
    const q = new URLSearchParams({ limit: 30 });
    const res = await fetch(`/api/rooms/${encodeURIComponent(room.id)}/history?${q}`);
    const data = await res.json();
    if (historyState.roomId !== room.id) return; // 弹窗已切到别的房间
    historyState.events = data.events;          // 服务端升序
    historyState.hasMore = data.hasMore;
    historyState.cursor = data.nextCursor;
  } catch (e) { toast('交接记录加载失败', 'error'); }
  historyState.loading = false;
  renderHistory();
}
document.getElementById('historyMore').onclick = async () => {
  if (historyState.loading || !historyState.hasMore || historyState.cursor == null) return;
  historyState.loading = true;
  renderHistory();
  try {
    const q = new URLSearchParams({ limit: 30, beforeSeq: historyState.cursor });
    const res = await fetch(`/api/rooms/${encodeURIComponent(historyState.roomId)}/history?${q}`);
    const data = await res.json();
    // 服务端返回更早一页（升序），拼到现有列表前面；seq 去重保险
    const known = new Set(historyState.events.map(e => e.seq));
    historyState.events = [...data.events.filter(e => !known.has(e.seq)), ...historyState.events];
    historyState.hasMore = data.hasMore;
    historyState.cursor = data.nextCursor;
  } catch (e) { toast('更早记录加载失败', 'error'); }
  historyState.loading = false;
  renderHistory();
};

