      'X-Role': 'CLEANER', 'X-User-Id': L('u-c'), 'X-User-Name': L('保洁-王姐'),
    });
    await postTransition(base, 'R303', { action: 'SUBMIT_CLEAN', expectedVersion: 2 }, {
      'X-Role': 'CLEANER', 'X-User-Id': L('u-c'), 'X-User-Name': L('保洁-王姐'),
    });
    const r2 = await api(base, 'POST', '/api/rooms/R303/transitions', {
      action: 'REJECT_INSPECTION', expectedVersion: 3, reason: '因'.repeat(201),
    }, MANAGER_HEADERS);
    assert.equal(r2.status, 400);
    const hist = await (await fetch(`${base}/api/rooms/R303/history?limit=5`)).json();
    assert.ok(!hist.events.some(e => e.action === 'REJECT_INSPECTION'));
  } finally {
    child.kill();
  }
});

