test('全局动态：三维筛选 + 向更早翻页（HTTP），筛选子集内不重不漏', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    const cleaner = { 'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐') };
    // R303: CLAIM(seq9) SUBMIT(seq10)
    await postTransition(base, 'R303', { action: 'CLAIM', expectedVersion: 1 }, cleaner);
    await postTransition(base, 'R303', { action: 'SUBMIT_CLEAN', expectedVersion: 2 }, cleaner);
    // R304: CLAIM(seq11)
    await postTransition(base, 'R304', { action: 'CLAIM', expectedVersion: 1 }, {
      'X-Role': 'CLEANER', 'X-User-Id': 'u-c2', 'X-User-Name': L('保洁-李姐'),
    });

    // 按包厢筛选：R303 共 2 条流转（CLAIM/SUBMIT，播种 CHECK_OUT 也属于 R303 → 3 条）
    const byRoom = await (await fetch(`${base}/api/feed?roomId=R303&limit=50`)).json();
    assert.deepEqual(byRoom.events.map(e => e.action), ['CHECK_OUT', 'CLAIM', 'SUBMIT_CLEAN']);
    assert.ok(byRoom.events.every(e => e.roomId === 'R303'));

    // 按动作筛选：全局 CLAIM 只有 R303/R304 两条（都是 seq9/11）
    const byAction = await (await fetch(`${base}/api/feed?action=CLAIM&limit=50`)).json();
    assert.deepEqual(byAction.events.map(e => e.roomId), ['R303', 'R304']);

    // 按操作人姓名子串：只出王姐的动作
    const byOp = await (await fetch(`${base}/api/feed?operator=${encodeURIComponent('王姐')}&limit=50`)).json();
    assert.ok(byOp.events.length >= 2);
    assert.ok(byOp.events.every(e => e.operatorName.includes('王姐')));

    // 组合：R303 + CLAIM 唯一一条
    const combo = await (await fetch(`${base}/api/feed?roomId=R303&action=CLAIM&limit=50`)).json();
    assert.equal(combo.events.length, 1);
    assert.equal(combo.events[0].roomId, 'R303');
    assert.equal(combo.events[0].action, 'CLAIM');

    // 非法动作 / 不存在包厢 → 400/404
    assert.equal((await fetch(`${base}/api/feed?action=NOPE`)).status, 400);
    assert.equal((await fetch(`${base}/api/feed?roomId=NOPE`)).status, 404);
    // afterSeq 与 beforeSeq 同传 → 400
    assert.equal((await fetch(`${base}/api/feed?afterSeq=1&beforeSeq=5`)).status, 400);

    // 向更早翻页（limit=2）：首屏最近两条，再用 nextCursor 拿更早的，拼接无重复无遗漏
    const p1 = await (await fetch(`${base}/api/feed?limit=2`)).json();
    assert.equal(p1.events.length, 2);
    assert.equal(p1.hasMore, true);
    const p2 = await (await fetch(`${base}/api/feed?beforeSeq=${p1.nextCursor}&limit=2`)).json();
    assert.ok(p2.events.every(e => e.seq < Math.min(...p1.events.map(x => x.seq))));
    // 两页 seq 不相交
    const s1 = new Set(p1.events.map(e => e.seq));
    assert.ok(p2.events.every(e => !s1.has(e.seq)));
  } finally {
    child.kill();
  }
});

test('交接记录弹窗：history 分页（beforeSeq）可一直翻到最早，不重不漏', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // R303 走完整循环产生多条：CHECK_OUT(seed,1) CLAIM(2) SUBMIT(3) REJECT→CLEANING(4)
    const cleaner = { 'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐') };
    await postTransition(base, 'R303', { action: 'CLAIM', expectedVersion: 1 }, cleaner);
    await postTransition(base, 'R303', { action: 'SUBMIT_CLEAN', expectedVersion: 2 }, cleaner);
    await postTransition(base, 'R303', {
      action: 'REJECT_INSPECTION', expectedVersion: 3, reason: '返工',
    }, MANAGER_HEADERS);

    // 每页 2 条，从最近向更早翻
    let page = await (await fetch(`${base}/api/rooms/R303/history?limit=2`)).json();
    const seen = new Set(page.events.map(e => e.seq));
    assert.equal(page.events.length, 2);
    assert.equal(page.hasMore, true);
    let guard = 0;
    while (page.hasMore && guard++ < 10) {
      page = await (await fetch(`${base}/api/rooms/R303/history?limit=2&beforeSeq=${page.nextCursor}`)).json();
      for (const e of page.events) {
        assert.ok(!seen.has(e.seq), `seq ${e.seq} 重复`);
        seen.add(e.seq);
      }
    }
    assert.equal(seen.size, 4, '应翻出全部 4 条');
  } finally {
    child.kill();
  }
});
