input.new_string:
// 按动作筛选：全局 CLAIM 含播种的 R305/R307 和新建的 R303/R304，全部都是 CLAIM
const byAction = await (await fetch(`${base}/api/feed?action=CLAIM&limit=50`)).json();
assert.ok(byAction.events.every(e => e.action === 'CLAIM'));
const claimRooms = byAction.events.map(e => e.roomId);
assert.deepEqual(claimRooms.slice(-2), ['R303', 'R304']);
assert.ok(claimRooms.includes('R305') && claimRooms.includes('R307'));

