input.command:
rm -rf /tmp/ktv-feed2 && mkdir -p /tmp/ktv-feed2
setsid env DATA_DIR=/tmp/ktv-feed2 PORT=4513 node src/server.js > /tmp/ktv-feed2.log 2>&1 < /dev/null &
sleep 1
cat > /tmp/check-feed.mjs << 'EOF'
const B = 'http://localhost:4513';
const H = { 'Content-Type':'application/json','X-Role':'CLEANER','X-User-Id':'u-c1','X-User-Name':encodeURIComponent('保洁-王姐') };
const post = (room, body) => fetch(`${B}/api/rooms/${room}/transitions`, { method:'POST', headers:H, body:JSON.stringify(body) }).then(r=>r.json());
await post('R303', { action:'CLAIM', expectedVersion:1 });
await post('R303', { action:'SUBMIT_CLEAN', expectedVersion:2 });
// R303 现在 3 条：CHECK_OUT(8) CLAIM SUBMIT；每页 1 条向更早翻
let cur = null, pages = [], guard = 0;
while (guard++ < 10) {
  const q = new URLSearchParams({ roomId:'R303', limit:1 });
  if (cur != null) q.set('beforeSeq', cur);
  const d = await (await fetch(`${B}/api/feed?${q}`)).json();
  pages.push(...d.events.map(e => `${e.seq}:${e.action}`));
  if (!d.hasMore) break;
  cur = d.nextCursor;
}
console.log('R303 筛选翻页顺序（新→旧）:', pages.join(' '));
const uniq = new Set(pages);
console.log('无重复:', uniq.size === pages.length, '| 共 3 条:', pages.length === 3);
process.exit(0);
EOF
node /tmp/check-feed.mjs
fuser -k 4513/tcp 2>/dev/null; rm -rf /tmp/ktv-feed2 /tmp/ktv-feed2.log /tmp/check-feed.mjs; true

input.old_string:
GET  /api/rooms                     看板快照（在营 + 停用房间均在 rooms 中，停用项 active=false）
GET  /api/feed?afterSeq=&limit=50   全局交接动态（升序，含 transition/manage 两类条目）；
                                    不传 afterSeq 取最近 limit 条，传 afterSeq 返回 seq 更大的
                                    事件，缺口过大时按 hasMore / nextCursor 从最早一页向后翻
GET  /api/rooms/:id/history?limit=50
POST /api/rooms                     新增包厢（仅值班经理）body: { id?(留空自动), name }
PATCH /api/rooms/:id/name           改名（仅值班经理）body: { name }
PATCH /api/rooms/:id/active         停用/启用（仅值班经理）body: { active, reason?(停用必填展示) }
POST /api/rooms/:id/transitions
     body: { action, expectedVersion, reason?, idempotencyKey? }
     header 可选: Idempotency-Key
GET  /api/events                    SSE（事件: transition / room / alerts / hello）

